head.script:

        	scwin.onpageload = function() {
            };

            scwin.tabControl1_ontabsplit = function(dragIndex, e) {
                var options = {
                    left: e.screenX + 'px',
                    top: e.screenY + 'px',
                };
                var tabInfo = tabControl1.getTabInfo();
                var src = "";
                for (var i = 0; i < tabInfo.length; i++) {
                    if (tabInfo[i].currentTabIndex == dragIndex) {
                        src = tabInfo[i].src;
                        break;
                    }
                }
                $p.openPopup(src, options);
                return true; // true 리턴시 해당 탭 닫힘.
            }


	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate = function() {
		scwin.simulateWrapper('#tabControl1_tab_tabs1', 'drag-n-drop', {
			dx: 50,
			dy: 0
		});
	}

	scwin.checkVal = function() {
		var temp = WebSquare.logger.getLog();
		return temp.indexOf('screenX') == -1;
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tabControl1_tab_tabs1').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
